solutionCode:
export function descreverAmbiente(versao) {
  if (versao === undefined || versao === '') {
    return 'Node.js — JavaScript fora do navegador, sem acesso ao DOM, com acesso a arquivos e rede.';
  }
  return `Node.js ${versao} — JavaScript fora do navegador, sem acesso ao DOM, com acesso a arquivos e rede.`;
}
